import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"更新日志阅读说明","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md","lastUpdated":0}`),a={name:`guide/changelog.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="更新日志阅读说明" tabindex="-1">更新日志阅读说明 <a class="header-anchor" href="#更新日志阅读说明" aria-label="Permalink to “更新日志阅读说明”">​</a></h1><p>本页用于说明当前文档与源码能力的同步重点，并提供升级时的检查路径。完整版本变化仍应结合各模块目录下的 <code>CHANGELOG.md</code>、默认配置文件和发行包说明一起阅读。当前 14 个 runtime 模块中有 13 个提供 <code>CHANGELOG.md</code>；<strong>EmakiMobs 尚无该文件</strong>，该模块的版本变化请以默认 <code>config.yml</code> 与发行包说明为准。</p><h2 id="旧版-configured-item-自动迁移已下线" tabindex="-1">旧版 configured-item 自动迁移已下线 <a class="header-anchor" href="#旧版-configured-item-自动迁移已下线" aria-label="Permalink to “旧版 configured-item 自动迁移已下线”">​</a></h2><ul><li>运行时<strong>不再自动迁移</strong>旧版物品字段：CoreLib 共享 GUI 与 EmakiItem <code>items/</code> 的定义应直接使用 canonical <code>item.source</code>、<code>item.amount</code>、<code>item.components</code>。</li><li>历史 <code>material</code>、<code>display_name</code>、<code>lore</code>、模型数据与附魔等旧字段不会被改写或补齐；旧写法不会再被静默修补，也不会被自动升级。</li><li>其余模块的旧写法仍可用各模块的一次性命令处理（先在预览模式确认，再加 <code>confirm</code> 应用）：<code>/emakiforge convert-legacy</code>、<code>/emakigem convert-legacy</code>、<code>/emakistrengthen convert-legacy</code>、<code>/emakilevel convert-legacy</code>、<code>/emakicooking convert-legacy</code>。转换器是迁移设施而非插件功能，其整包下线清单见 <a href="./../modules/corelib/legacy-converter-retirement.html">旧配置转换器下线清单</a>。</li><li>正式服升级仍建议先备份完整配置目录。</li></ul><h2 id="corelib-边界调整-领域协议迁回业务模块" tabindex="-1">CoreLib 边界调整：领域协议迁回业务模块 <a class="header-anchor" href="#corelib-边界调整-领域协议迁回业务模块" aria-label="Permalink to “CoreLib 边界调整：领域协议迁回业务模块”">​</a></h2><p>CoreLib 不再持有领域协议与扩展点，二次开发时请改用新归属：</p><ul><li>物品层预览 SPI（<code>ItemLayerPreviewProvider</code>、<code>ItemLayerPreviewRequest</code> 等）已从 CoreLib 删除，现由 <code>EmakiItemApi</code> 的 <code>emaki.jiuwu.craft.item.api.preview</code> 持有。</li><li>装备技能 PDC key 与编解码现唯一由 <code>EmakiSkillsApi</code> 的 <code>emaki.jiuwu.craft.skills.api.pdc.EquipmentSkillPdcCodec</code> 持有。</li><li>属性 PDC 与属性服务契约现唯一权威在 <code>EmakiAttributeApi</code> 的 <code>emaki.jiuwu.craft.attribute.api.PdcAttributeAccess</code> 与完整 <code>PdcAttributePayload</code>，取用路径为 <code>EmakiAttributeApi.extensions().pdc()</code>。</li><li>CoreLib 侧的兼容适配器已在 CoreLib <code>4.6.7</code> 全部移除：<code>SkillPdcGateway</code>、<code>PdcAttributeGateway</code> 与镜像类型 <code>PdcAttributeApi</code>、<code>PdcAttributePayloadSnapshot</code>、<code>EmakiAttributeBridge</code> 不再存在，仍引用它们的外部代码会抛 <code>NoClassDefFoundError</code>。</li></ul><h2 id="本轮文档更新重点-2026-09-18" tabindex="-1">本轮文档更新重点（2026-09-18） <a class="header-anchor" href="#本轮文档更新重点-2026-09-18" aria-label="Permalink to “本轮文档更新重点（2026-09-18）”">​</a></h2><p>本轮按当前源码、POM、默认资源与描述符全面复核文档，主要变更如下：</p><ul><li><strong>版本线同步</strong>：14 个 runtime/API 模块的模块版本、Jar 文件名、Maven/Gradle 坐标与 <code>config.yml</code>、<code>lang/*.yml</code> 资源版本全部对齐当前 POM；README 与文档站的模块版本表一并更新。</li><li><strong>仓库结构</strong>：默认 reactor 为 23 个模块（14 个 API + 9 个 runtime）；<code>private-modules</code> profile 额外追加 5 个 runtime（Skills、Gem、Item、Storage、Accessory），启用后共 28 个。README 与快速开始中的模块数量、profile 归属已按 <code>pom.xml</code> 更正。</li><li><strong>CoreLib 数值动作</strong>：新增 <code>take_food</code> 段；生命、饱食度、经验、货币与物品数量类段改为显式校验（负数与非有限值返回 <code>INVALID_CONFIG</code>，不再静默钳制）；扣除不足返回 <code>REJECTED</code> 且不做部分扣除；新增 <code>action.audit</code> 审计日志说明。</li><li><strong>CoreLib 动画</strong>：补充 <code>api.animation</code> 契约与 <code>registerAnimation</code> / <code>playAnimationAsync</code> / <code>stopAnimation</code> / <code>addAnimationListener</code> 门面说明；纠正“动画定义在 CoreLib reload 后需要重放”的错误描述——动画注册表在 reload 后存活，需要重建回调的是动作段表；K 帧示例改为合法管道语法。</li><li><strong>物品来源别名</strong>：VANILLA 别名补 <code>mc</code>；删除 ECOITEMS 下无效的 <code>eco</code> 别名。</li><li><strong>EmakiMobs</strong>：<code>skills</code> / <code>attributes</code> 改为当前键 <code>actions</code> / <code>ea_attributes</code>（旧键回退并提示 WARN）；补齐 <code>list</code> / <code>info</code> / <code>kill</code> / <code>count</code> / <code>debug</code> 命令与权限；公开 API 补 <code>identify</code>、<code>refresh</code> 与 <code>registerCustomSpawner</code> 三参签名；<code>model.api</code> 与 <code>model.lod</code> 标注为“解析但当前未生效”，LOD 改为近/远两档；模型与动作示例改为合法管道语法；<code>drain_timeout_seconds</code> 标注为兼容保留项。</li><li><strong>EmakiAttribute</strong>：补充 MythicMobs 名称中 <code>&amp;</code> 颜色码转换为 MiniMessage 的说明。</li><li><strong>EmakiAccessory</strong>：新增玩家数据文件结构（<code>pages.&lt;页&gt;.&lt;槽位&gt;</code>）与 v1→v2 自动升级、结构不可识别时拒绝落盘的说明；修正技能载荷编解码类名。</li><li><strong>配置键与权限修正</strong>：Level 删除文档中不存在的 <code>storage</code> 段与 <code>pdc.sync_on_*</code>；Station 分解配方改用 <code>item_sources</code>（<code>input_source</code> 为旧键）、说明 <code>tags</code> 不参与工位绑定、<code>weight</code> 非法值回退 1.0；Skills 补 <code>cast_mode.enabled</code> 与 <code>trigger_settings.legacy_dispatch_cancelled_events</code>；修正 Skills / Storage 的 <code>help</code> 命令权限；Gem 删除不存在的占位符与 <code>gem_slot_presentation</code>、明确宝石 ID 取自 <code>id</code> 字段、补 <code>item_sources</code> 判定项；Forge 修正 <code>material_id</code> 回退顺序。</li><li><strong>删除已废弃内容</strong>：旧版 configured-item 自动迁移的描述已替换为下线说明（见上节）。</li></ul><h2 id="历史同步重点-保留备查" tabindex="-1">历史同步重点（保留备查） <a class="header-anchor" href="#历史同步重点-保留备查" aria-label="Permalink to “历史同步重点（保留备查）”">​</a></h2><p>以下为更早几轮文档同步的内容，保留用于追溯；其中被本轮修正或已下线的部分以上文与各模块页面为准。</p><ul><li><strong>平台与调度</strong><ul><li>各插件 <code>paper-plugin.yml</code> 已声明 Paper 1.21.8+ 与 Folia 支持；CoreLib 新增 Folia 调度适配，业务模块的延迟任务、异步任务、GUI 回主线程刷新和显示实体刷新应通过统一调度入口运行。</li><li>文档中的环境要求已同步为 Paper 1.21.8+，并同步当前 Folia 支持声明。</li></ul></li><li><strong>GUI 与物品展示</strong><ul><li>GUI 槽位以 <code>item</code> 作为当前结构化字段；动态信息槽、确认槽、预览槽优先尊重模板中的 <code>item</code>、<code>display_name</code>、<code>lore</code> 和组件配置。</li><li>EmakiGem 镶嵌、开孔、升级界面打开时不再自动从玩家主手或背包补入目标物品，目标装备与材料需要玩家手动放入。</li><li>EmakiSkills 技能面板、触发器选择界面以及 EmakiStrengthen 的预览/确认类动态槽位已对齐上述 GUI 模板优先规则。</li></ul></li><li><strong>属性与 PDC</strong><ul><li>Attribute 支持区间随机值，Lore 与 PDC 解析可识别百分比和整数区间，快照会保留区间贡献的最小值、最大值与实际取值。</li><li><code>variables</code> 与 <code>ea_attributes</code> 语义边界更清晰：变量用于文本与占位符上下文，真实属性输出应写入显式 <code>ea_attributes</code>。</li><li>近期清理了 <code>ea_attribute_meta</code> 相关逻辑，材料、宝石、物品和强化配置不应再依赖该字段作为属性元数据入口。</li></ul></li><li><strong>Cooking 配方</strong><ul><li>配方结果统一使用 <code>result.&lt;branch&gt;.outputs/actions</code> 结构；成功、提前、过度、欠熟、过熟、非法等分支都按同一模型描述。</li><li>新增配方完成条件系统，配方可以在产出前检查条件；操作台默认交互按键也按当前源码重新整理。</li><li>工位悬浮文本展示、展示实体后端和刷新配置已进入当前配置线。</li></ul></li><li><strong>Level</strong><ul><li>新增 EmakiLevel / EmakiLevelApi 等级系统模块，提供多等级类型、经验来源、升级需求、PDC、PlaceholderAPI、CoreLib Action、MythicMobs Drop 和 EmakiAttribute 属性贡献桥接。</li><li>VitePress 已新增详细 Level 模块文档，并在快速开始、项目介绍和架构总览中补充等级成长模块。</li></ul></li><li><strong>Forge / Gem / Strengthen / Item / Skills</strong><ul><li>Forge 材料效果只显示当前效果类型自己的参数，<code>quality_modify</code> 使用 <code>tier</code>，<code>capacity_bonus</code> 使用 <code>value</code>。</li><li>Gem 宝石物品会在获取、重载和 GUI 复刻时按当前定义刷新名称、Lore、模型和等级展示。</li><li>Skills、Strengthen、Forge、Gem、Item 的技能效果统一使用 <code>es_skills</code> 列表写法，不再把旧单值字段作为当前文档推荐写法。</li></ul></li></ul><h3 id="新增和补充" tabindex="-1">新增和补充 <a class="header-anchor" href="#新增和补充" aria-label="Permalink to “新增和补充”">​</a></h3><ul><li><strong>Attribute</strong><ul><li>新增配置目录说明，补充 <code>config.yml</code>、<code>attribute_balance.yml</code>、<code>attributes/</code>、<code>damage_types/</code>、<code>conditions/</code>、<code>lore_formats/</code> 的职责。</li><li>新增属性衰减曲线页面，说明 <code>logarithmic</code>、<code>sqrt</code>、<code>piecewise_linear</code> 三类衰减规则。</li><li>伤害系统补充 <code>synthetic_hit_feedback</code>，说明接管原版伤害后的击退与受伤音效反馈。</li></ul></li><li><strong>Gem</strong><ul><li>新增开孔器系统页面，说明 <code>socket_openers</code>、开孔器材料、插槽类型和失败反馈。</li><li>更新镶嵌成功率，改为当前 <code>inlay_success</code> 配置结构。</li><li>补充宝石升级全局成功率和失败惩罚。</li></ul></li><li><strong>Skills</strong><ul><li>新增技能状态栏页面，说明 <code>actionbar</code> 模板、刷新间隔和施法模式展示。</li><li>补充脚本引擎全局限制，包括每阶段动作行数和单动作目标数量。</li><li>补充 <code>combo_attack</code> 被动触发器和被动触发器全局设置。</li></ul></li><li><strong>Cooking</strong><ul><li>命令与权限补充 <code>/ec debug</code>、烤炉、榨汁机、发酵桶权限。</li><li>工位系统补充展示实体后端、展示距离、刷新间隔、炒锅翻炒动画和烫伤机制。</li></ul></li><li><strong>Forge</strong><ul><li>新增锻造历史记录页面，用于说明锻造行为追踪、自动保存和排查用途。</li><li>品质系统保留品质池、保底、品质物品元数据和确定性算法说明。</li></ul></li><li><strong>Strengthen</strong><ul><li>分支树页面补充分支配方文件和强化转移设计要点。</li></ul></li><li><strong>Item</strong><ul><li>命令页面补充 <code>/ei debug</code> 和 <code>emakiitem.debug</code> 权限。</li></ul></li></ul><h3 id="删除和修正" tabindex="-1">删除和修正 <a class="header-anchor" href="#删除和修正" aria-label="Permalink to “删除和修正”">​</a></h3><ul><li><strong>Gem 命令修正</strong><ul><li>清理已不属于当前命令路由的旧管理入口。</li><li>当前命令统一为 <code>/emakigem gui [inlay|open|upgrade]</code>、<code>reload</code>、<code>inspect</code>、<code>clearstate</code>、<code>debug</code>。</li><li>权限改为 <code>emakigem.use</code>、<code>emakigem.reload</code>、<code>emakigem.admin</code>、<code>emakigem.debug</code>。</li></ul></li><li><strong>Skills 命令修正</strong><ul><li>技能界面入口统一为 <code>/eskills gui</code>。</li><li>清理已不属于当前命令路由的旧触发器管理入口。</li><li>补充 <code>/eskills clearslot &lt;player&gt; &lt;slot&gt;</code>。</li><li><code>castmode</code> 明确为 <code>/eskills castmode &lt;on|off|toggle&gt;</code>。</li></ul></li><li><strong>Cooking 权限修正</strong><ul><li>榨汁机盛取权限使用 <code>emakicooking.station.juicer.collect</code>。</li><li>发酵桶开始权限使用 <code>emakicooking.station.fermentation_barrel.start</code>。</li><li>工位权限统一采用 <code>emakicooking.station.*</code> 形式。</li></ul></li></ul><h2 id="模块版本线说明" tabindex="-1">模块版本线说明 <a class="header-anchor" href="#模块版本线说明" aria-label="Permalink to “模块版本线说明”">​</a></h2><p>当前源码中各模块版本并不完全相同，应以各模块 <code>src/main/resources/config.yml</code> 和 <code>pom.xml</code> 为准：</p><table tabindex="0"><thead><tr><th>模块</th><th>当前默认配置版本</th></tr></thead><tbody><tr><td>EmakiCoreLib</td><td><code>4.8.8</code></td></tr><tr><td>EmakiAttribute</td><td><code>4.8.1</code></td></tr><tr><td>EmakiForge</td><td><code>4.8.1</code></td></tr><tr><td>EmakiStrengthen</td><td><code>4.8.2</code></td></tr><tr><td>EmakiCooking</td><td><code>4.3.1</code></td></tr><tr><td>EmakiLevel</td><td><code>1.6.1</code></td></tr><tr><td>EmakiCodex</td><td><code>1.1.0</code></td></tr><tr><td>EmakiStation</td><td><code>1.1.3</code></td></tr><tr><td>EmakiGem</td><td><code>2.8.2</code></td></tr><tr><td>EmakiSkills</td><td><code>2.8.1</code></td></tr><tr><td>EmakiItem</td><td><code>2.8.1</code></td></tr><tr><td>EmakiStorage</td><td><code>1.1.0</code></td></tr><tr><td>EmakiAccessory</td><td><code>1.1.2</code></td></tr><tr><td>EmakiMobs</td><td><code>1.0.3</code></td></tr></tbody></table><p>当前 14 个模块的 <code>config.yml</code>、<code>lang/*.yml</code> 资源版本与各自 <code>pom.xml</code> 完全一致，因此这张表同时也是模块发布版本表。个别模块的源码内部迁移常量（<code>AppConfig.CURRENT_VERSION</code>）与此不同轨，不要混用：Codex 为 <code>1.0.14</code>、Cooking 为 <code>3.3.14</code>、Forge 为 <code>4.5.11</code>、Gem 为 <code>2.7.8</code>、Mobs 为 <code>1.0.0</code>、Skills 为 <code>2.5.11</code>、Station 为 <code>1.0.2</code>、Storage 为 <code>1.0.6</code>。</p><p>装备技能 PDC 契约已并入 <code>emaki-skills-api</code>，不再有独立的 <code>emaki-skills-protocol</code> 构件。</p><p>不同模块的版本号代表各自发行节奏，不表示功能重要性。升级时应按实际安装模块分别比对默认配置。</p><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to “推荐阅读顺序”">​</a></h2><ol><li>阅读目标模块首页，确认模块职责和依赖关系。</li><li>阅读命令与权限页面，先完成权限组规划。</li><li>阅读配置目录或核心功能页面，确认默认目录和文件用途。</li><li>阅读具体功能页，例如宝石开孔、技能触发器、属性衰减、锻造品质、烹饪工位。</li><li>修改配置后使用对应模块的 reload、inspect、debug 或 lint 命令验证。</li><li>正式服升级前，在测试服导入真实装备与玩家数据进行抽样验证。</li></ol><h2 id="升级前检查清单" tabindex="-1">升级前检查清单 <a class="header-anchor" href="#升级前检查清单" aria-label="Permalink to “升级前检查清单”">​</a></h2><ul><li>备份整个 <code>plugins/Emaki*/</code> 配置目录。</li><li>备份玩家数据、装备数据、Cooking 工位数据、Station 队列数据、Accessory 饰品数据和经济数据。</li><li>不要直接覆盖旧配置；先用默认配置对比新增字段，再逐项合并。旧版 configured-item 自动迁移已下线，旧物品定义不会在启动时被自动转换，必须手工改为 canonical <code>item.source</code> / <code>item.amount</code> / <code>item.components</code> 结构。</li><li>检查命令和权限是否按当前文档修正。</li><li>检查 Attribute 是否启用 <code>hard_lock_damage</code>，并确认环境伤害映射符合服务器预期。</li><li>检查 Gem 是否合并 <code>socket_openers</code>、<code>inlay_success</code>、<code>upgrade</code> 全局配置。</li><li>检查 Skills 是否合并 <code>actionbar</code>、<code>script_engine</code>、<code>passive_trigger_settings</code>。</li><li>检查 Cooking 是否合并 <code>oven</code>、<code>juicer</code>、<code>fermentation_barrel</code> 工位、GUI 和权限。</li><li>检查 Forge 品质、历史记录和条件失败策略是否符合当前玩法。</li><li>检查 Item 自动更新和修复配置是否会影响旧物品。</li></ul><h2 id="排查建议" tabindex="-1">排查建议 <a class="header-anchor" href="#排查建议" aria-label="Permalink to “排查建议”">​</a></h2><ul><li>配置加载失败时，先看控制台首个 YAML 解析错误，通常后续错误都是连锁结果。</li><li>物品属性异常时，先确认 CoreLib 装配层是否重建，再检查 Attribute PDC 输出。</li><li>GUI 无法操作时，优先检查权限、槽位配置、模板 ID 和物品来源。</li><li>成功率、品质、强化等随机玩法异常时，先检查公式变量、保底计数和失败处理策略。</li><li>涉及跨模块效果时，按 CoreLib → Attribute/Skills → 业务模块的顺序排查。</li></ul>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};